/**
 * Server-side helper to resolve the active studio context for the current user.
 *
 * Resolution order:
 *  1. Cookie `inkos_active_studio` (httpOnly, SameSite=Lax, Max-Age 31536000)
 *  2. First membership ordered by studio_members.created_at ASC
 *
 * URL param `?studio=X` is honoured via <StudioParamSync> client component on mount —
 * it fires a POST to /api/context/set-studio which writes the cookie, then calls
 * router.refresh(). Layout reads only cookie + fallback (no search param in layout).
 *
 * Throws if the user has no studio memberships (caller redirects to /onboarding).
 */

import { cache } from 'react'
import { cookies } from 'next/headers'
import { createClient } from '@/lib/supabase/server'
import type { Database } from '@/lib/supabase/types'
import type { PlanTier } from '@/lib/billing/feature-gate'

export type StudioRow = Database['public']['Tables']['studios']['Row']
export type StudioMemberRow = Database['public']['Tables']['studio_members']['Row']
export type StudioMemberRole = StudioMemberRow['role']

export interface StudioMembership {
  studioId: string
  studio: StudioRow
  role: StudioMemberRole
  /** Resolved subscription plan for this studio. Defaults 'solo' if no active sub. */
  plan: PlanTier
}

export interface ActiveStudioContext {
  studioId: string
  studio: StudioRow
  role: StudioMemberRole
  plan: PlanTier
  allMemberships: StudioMembership[]
}

export class NoStudioMembershipError extends Error {
  constructor() {
    super('User has no studio memberships')
    this.name = 'NoStudioMembershipError'
  }
}

/**
 * React `cache()` wraps the fetcher so any Server Component in the same request
 * that calls `getActiveStudio()` after the layout already did hits an in-memory
 * cache instead of re-querying Supabase. The cached value is scoped to a single
 * request; no cross-request sharing.
 */
export const getActiveStudio = cache(_getActiveStudio)

async function _getActiveStudio(): Promise<ActiveStudioContext> {
  const supabase = await createClient()

  // 1. Identify current user
  const {
    data: { user },
    error: authError,
  } = await supabase.auth.getUser()
  if (authError || !user) {
    throw new NoStudioMembershipError()
  }

  // 2. Fetch all memberships with studio data, ordered by created_at ASC
  const { data: rows, error: memberError } = await supabase
    .from('studio_members')
    .select(
      `
      studio_id,
      role,
      created_at,
      studios (
        id, name, slug, timezone, locale, currency, brand_color, logo_url, plan_id,
        custom_domain, custom_domain_verified, custom_domain_verified_at,
        white_label_enabled, custom_favicon_url, custom_email_from_name,
        custom_email_reply_to, powered_by_hidden, status, created_at, updated_at
      )
      `
    )
    .eq('user_id', user.id)
    .is('deactivated_at', null)
    .order('created_at', { ascending: true })

  if (memberError || !rows || rows.length === 0) {
    throw new NoStudioMembershipError()
  }

  // 3. S19 perf — batch subscription lookup (was N+1 per studio). Single query
