'use client'

import { useMemo } from 'react'
import {
  Sidebar,
  SidebarContent,
  SidebarFooter,
  SidebarHeader,
} from '@/components/ui/sidebar'
import { SidebarNavGroup } from '@/components/app/sidebar/SidebarNavGroup'
import type { DynamicBadgeCounts } from '@/components/app/sidebar/SidebarNavGroup'
import { APP_NAV, type NavRole } from '@/components/app/sidebar/nav-config'
import { BookingLinkWidget } from '@/components/app/sidebar/BookingLinkWidget'
import { SidebarFavorites } from '@/components/app/sidebar/SidebarFavorites'
import { SidebarUserFooter } from '@/components/app/sidebar/SidebarUserFooter'
import { StudioSwitcher } from '@/components/shared/StudioSwitcher'
import type { PlanTier } from '@/lib/billing/feature-gate'
import type { StudioMembership } from '@/lib/context/active-studio'
import type { UserPinnedItem } from '@/lib/pinned-items/pinned'

interface AppSidebarProps {
  plan: PlanTier
  studioName: string
  studioLogoUrl?: string | null
  studioSlug: string
  role: NavRole
  locationCount: number
  /** Serialized from server — Set<string> → JSON array → passed as prop */
  permissionKeys?: string[]
  /** Dynamic badge counts from server (inbox, calendar, clients, inventory) */
  dynamicBadges?: DynamicBadgeCounts
  /** S15: all studio memberships — single item = no switcher rendered */
  allMemberships: StudioMembership[]
  /** S15: active studio id */
  currentStudioId: string
  /** User info for footer */
  userName: string
  userEmail: string
  userAvatarUrl?: string | null
  /** S22: pinned items for Favorites section */
  pinnedItems?: UserPinnedItem[]
}

export function AppSidebar({
  plan,
  studioName,
  studioLogoUrl,
  studioSlug,
  role,
  locationCount,
  permissionKeys = [],
  dynamicBadges = {},
  allMemberships,
  currentStudioId,
  userName,
  userEmail,
  userAvatarUrl,
  pinnedItems = [],
}: AppSidebarProps) {
  const permissions = useMemo(() => new Set(permissionKeys), [permissionKeys])

  const navGroups = useMemo(() => {
    return APP_NAV
      .filter((group) => !(group.condition === 'multi-location' && locationCount <= 1))
      .map((group) => ({
        ...group,
        items: group.items.filter((item) => {
          if (!item.requiredRoles.includes(role)) return false
          if (item.requiredPermission && !permissions.has(item.requiredPermission)) return false
          return true
        }),
      }))
      .filter((group) => group.items.length > 0)
  }, [role, locationCount, permissions])

  return (
    <Sidebar
      collapsible="icon"
      className={[
        'border-r border-sidebar-border',
        // Rust edge accent — barely-visible 1px gradient stripe on the right seam.
        // Fades in/out vertically so it reads as a brand signature, not a hard line.
        'relative after:pointer-events-none after:absolute after:right-0 after:top-0 after:h-full after:w-px',
        'after:bg-[linear-gradient(to_bottom,transparent_0%,oklch(58%_0.16_35/_0.12)_40%,oklch(58%_0.16_35/_0.12)_60%,transparent_100%)]',
      ].join(' ')}
    >
      {/* ── Brand header with ⌘K hint ─────────────────────────── */}
      <SidebarHeader className="border-b border-sidebar-border/60 px-3 py-2.5">
        <div className="flex items-center gap-2 group-data-[collapsible=icon]:justify-center">
          {studioLogoUrl ? (
            // eslint-disable-next-line @next/next/no-img-element
            <img
              src={studioLogoUrl}
              alt={studioName}
              className="h-8 w-8 shrink-0 rounded-md object-cover"
            />
          ) : (
            /* InkOS brand mark — italic `i` in Onyx tile per brand book */
            <div className="flex h-8 w-8 shrink-0 items-center justify-center rounded-md bg-foreground text-background">
              <span className="font-serif-italic text-xl leading-none">i</span>
            </div>
          )}
          <div className="flex min-w-0 flex-col leading-tight group-data-[collapsible=icon]:hidden">
            <span className="truncate text-[13px] font-bold tracking-tight text-sidebar-foreground">
              InkOS
            </span>
            <span className="truncate text-[10px] font-medium uppercase tracking-[0.08em] text-stone-brand">
              Studio OS
            </span>
          </div>
          {/* ⌘K hint pill */}
          <button
            type="button"
            aria-label="Open command palette (⌘K)"
            onClick={() => {
              // Dispatch synthetic ⌘K to trigger AppHeader's palette handler
              window.dispatchEvent(
                new KeyboardEvent('keydown', { key: 'k', metaKey: true, bubbles: true })
              )
            }}
            className="ml-auto flex h-5 shrink-0 items-center gap-0.5 rounded border border-border/50 bg-muted/30 px-1.5 text-[10px] font-mono text-muted-foreground/60 transition-colors hover:border-border hover:bg-muted/60 hover:text-muted-foreground group-data-[collapsible=icon]:hidden"
          >
            <span>⌘</span><span>K</span>
          </button>
        </div>

        {/* Studio switcher row */}
        <div className="mt-2 group-data-[collapsible=icon]:hidden">
          {allMemberships.length >= 2 ? (
            <StudioSwitcher
              currentStudioId={currentStudioId}
              allMemberships={allMemberships}
            />
          ) : (
            <div className="flex h-8 items-center gap-2 rounded-lg border border-border/40 bg-muted/20 px-2">
              <span className="truncate text-[13px] font-medium text-sidebar-foreground/80">
                {studioName}
              </span>
            </div>
          )}
        </div>

        {/* Booking link widget */}
        <BookingLinkWidget studioSlug={studioSlug} className="mt-1.5 mx-0" />
      </SidebarHeader>

      {/* ── Nav groups ────────────────────────────────────────── */}
      <SidebarContent className="gap-0 px-2 py-3">
        {navGroups.map((group, idx) => (
          <SidebarNavGroup
            key={group.label ?? '_unlabeled'}
            group={group}
            plan={plan}
            isFirst={idx === 0}
            dynamicBadges={dynamicBadges}
          />
        ))}

        {/* S22: Favorites */}
        <SidebarFavorites pinnedItems={pinnedItems} />
      </SidebarContent>

      {/* ── User footer ───────────────────────────────────────── */}
      <SidebarFooter className="p-0">
        <SidebarUserFooter
          userName={userName}
          userEmail={userEmail}
          userAvatarUrl={userAvatarUrl}
          role={role}
        />
      </SidebarFooter>
    </Sidebar>
  )
}

'use client'

import { useCallback, useEffect, useMemo, useState } from 'react'
import { usePathname, useRouter } from 'next/navigation'
import { LogOut, Menu, X } from 'lucide-react'
import { Avatar, AvatarFallback, AvatarImage } from '@/components/ui/avatar'
import { Button } from '@/components/ui/button'
import { ScrollArea } from '@/components/ui/scroll-area'
import { Sheet, SheetContent } from '@/components/ui/sheet'
import { cn } from '@/lib/utils'
import { APP_NAV, type NavItem, type NavRole } from '@/components/app/sidebar/nav-config'
import { PlanBadge } from '@/components/shared/PlanBadge'
import { StudioSwitcher } from '@/components/shared/StudioSwitcher'
import { LocationSwitcher } from '@/components/shared/LocationSwitcher'
import { BookingLinkWidget } from '@/components/app/sidebar/BookingLinkWidget'
import { hasFeature } from '@/lib/billing/feature-gate'
import type { PlanTier } from '@/lib/billing/feature-gate'
import type { StudioMembership } from '@/lib/context/active-studio'
import type { LocationRow } from '@/lib/context/active-location'
import type { DynamicBadgeCounts } from '@/components/app/sidebar/SidebarNavGroup'

interface MobileNavProps {
  userName: string
  userEmail: string
  userAvatarUrl: string | null | undefined
  studioName: string
  studioSlug?: string
  role: NavRole
  locationCount: number
  permissionKeys: string[]
  plan?: PlanTier
  dynamicBadges?: DynamicBadgeCounts
  onSignOut: () => void
  open?: boolean
  onOpenChange?: (open: boolean) => void
  allMemberships: StudioMembership[]
  currentStudioId: string
  currentLocationId: string | null
  allLocations: LocationRow[]
}

function getInitials(name: string): string {
  return name
    .split(' ')
    .slice(0, 2)
    .map((n) => n[0])
    .join('')
    .toUpperCase()
}

interface MobileNavItemProps {
  item: NavItem
  onNavigate: () => void
  isActive: boolean
  plan: PlanTier
  dynamicBadges: DynamicBadgeCounts
}

function MobileNavItem({ item, onNavigate, isActive, plan, dynamicBadges }: MobileNavItemProps) {
  const Icon = item.icon
  const router = useRouter()

  const isGated =
    !!item.requiredPlan &&
    !hasFeature(plan, item.featureKey ?? item.requiredPlan)

  const dynamicCount = item.dynamicBadge !== undefined ? (dynamicBadges[item.dynamicBadge] ?? 0) : 0
  const showCountBadge = item.badgeType === 'count' && dynamicCount > 0 && !isGated
  const showDotBadge = item.badgeType === 'dot' && dynamicCount > 0 && !isGated
  const showNewBadge = item.badgeType === 'new' && !isGated

  function formatCount(n: number): string {
    if (n >= 1000) return `${(n / 1000).toFixed(1)}k`
    return String(n)
  }

  function handleClick() {
    if (isGated) {
      onNavigate()
      router.push('/settings/subscription/billing')
      return
    }
    onNavigate()
    router.push(item.href)
  }

  return (
    <button
      type="button"
      className={cn(
        'flex w-full min-h-[44px] items-center gap-2.5 rounded-lg px-2.5 text-[13px] font-medium transition-colors text-left',
        isActive
          ? 'bg-accent text-accent-foreground'
          : 'text-muted-foreground hover:bg-muted/50 hover:text-foreground',
        isGated && 'opacity-60',
      )}
      onClick={handleClick}
      aria-current={isActive ? 'page' : undefined}
    >
      <Icon className="size-4 shrink-0" aria-hidden="true" />
      {item.label}

      {/* Plan badge for gated items */}
      {isGated && item.requiredPlan && item.requiredPlan !== 'solo' && (
        <PlanBadge plan={item.requiredPlan} className="ml-auto" />
      )}

      {/* Count badge */}
      {showCountBadge && (
        <span className="ml-auto inline-flex min-w-[20px] items-center justify-center rounded-full bg-muted px-1.5 py-0.5 text-[10px] font-semibold tabular-nums text-muted-foreground">
          {formatCount(dynamicCount)}
        </span>
      )}

      {/* Dot badge */}
      {showDotBadge && (
        <span className="ml-auto flex h-2 w-2 shrink-0 rounded-full bg-destructive" aria-label="Alert" />
      )}

      {/* New badge */}
      {showNewBadge && (
        <span className="ml-auto inline-flex items-center rounded-sm border border-rust/40 bg-rust-tint px-1.5 py-0.5 text-[9px] font-bold uppercase tracking-[0.08em] text-rust">
          NEW
        </span>
      )}
    </button>
  )
}

export function MobileNav({
  userName,
  userEmail,
  userAvatarUrl,
  studioName,
  studioSlug,
  role,
  locationCount,
  permissionKeys,
  plan = 'solo',
  dynamicBadges = {},
  onSignOut,
  open: externalOpen,
  onOpenChange: externalOnOpenChange,
  allMemberships,
  currentStudioId,
  currentLocationId,
  allLocations,
}: MobileNavProps) {
  const [internalOpen, setInternalOpen] = useState(false)
  const open = externalOpen !== undefined ? externalOpen : internalOpen
  const setOpen = useCallback((v: boolean) => {
    setInternalOpen(v)
    externalOnOpenChange?.(v)
  }, [externalOnOpenChange])
  const pathname = usePathname()

  const permissions = useMemo(() => new Set(permissionKeys), [permissionKeys])
  const navGroups = useMemo(() => {
    return APP_NAV
      .filter((group) => !(group.condition === 'multi-location' && locationCount <= 1))
      .map((group) => ({
        ...group,
        items: group.items.filter((item) => {
          if (!item.requiredRoles.includes(role)) return false
          if (item.requiredPermission && !permissions.has(item.requiredPermission)) return false
          return true
        }),
      }))
      .filter((group) => group.items.length > 0)
  }, [role, locationCount, permissions])

  useEffect(() => {
    setOpen(false)
  }, [pathname, setOpen])

  const showStudioSwitcher = allMemberships.length >= 2
  const showLocationSwitcher = allLocations.length >= 2

  return (
    <>
      <Button
        variant="ghost"
        className="flex h-11 w-11 items-center justify-center md:hidden"
        aria-label="Open navigation"
        aria-expanded={open}
        aria-controls="mobile-nav-sheet"
        onClick={() => setOpen(true)}
      >
        <Menu className="size-4" aria-hidden="true" />
      </Button>

      <Sheet open={open} onOpenChange={setOpen}>
        <SheetContent
          id="mobile-nav-sheet"
          side="left"
          className="w-[280px] p-0 flex flex-col"
          showCloseButton={false}
        >
          <div className="flex items-center gap-3 border-b border-border/60 px-4 py-4">
            <Avatar className="h-9 w-9 rounded-full ring-1 ring-border/60 shrink-0">
              {userAvatarUrl && <AvatarImage src={userAvatarUrl} alt={userName} />}
              <AvatarFallback className="rounded-full bg-foreground text-[11px] font-semibold text-background">
                {getInitials(userName)}
              </AvatarFallback>
            </Avatar>
            <div className="min-w-0 flex-1">
              <p className="truncate text-[13px] font-semibold leading-tight text-foreground">{userName}</p>
              <p className="truncate text-[11px] text-muted-foreground">{studioName}</p>
              <p className="truncate text-[10px] text-muted-foreground/60">{userEmail}</p>
            </div>
            <Button
              variant="ghost"
              className="h-8 w-8 shrink-0"
              onClick={() => setOpen(false)}
              aria-label="Close navigation"
            >
              <X className="size-4" aria-hidden="true" />
            </Button>
          </div>

          {/* Booking link widget in sheet header */}
          {studioSlug && (
            <div className="border-b border-border/60 px-3 py-2">
              <BookingLinkWidget studioSlug={studioSlug} className="mx-0" />
            </div>
          )}

          {(showStudioSwitcher || showLocationSwitcher) && (
            <div className="border-b border-border/60 px-3 py-2 space-y-1">
              {showStudioSwitcher && (
                <div className="flex items-center gap-2 min-h-[44px] px-1">
                  <span className="w-16 shrink-0 text-[11px] text-muted-foreground/60">Studio</span>
                  <StudioSwitcher currentStudioId={currentStudioId} allMemberships={allMemberships} />
                </div>
              )}
              {showLocationSwitcher && (
                <div className="flex items-center gap-2 min-h-[44px] px-1">
                  <span className="w-16 shrink-0 text-[11px] text-muted-foreground/60">Location</span>
                  <LocationSwitcher currentLocationId={currentLocationId} allLocations={allLocations} role={role as unknown as Parameters<typeof LocationSwitcher>[0]['role']} />
                </div>
              )}
            </div>
          )}

          <ScrollArea className="flex-1">
            <nav className="px-2 py-3 space-y-4" aria-label="Mobile navigation">
              {navGroups.map((group) => (
                <div key={group.label ?? '_unlabeled'}>
                  {/* Skip label for unlabeled group (null label) */}
                  {group.label !== null && (
                    <p className="mb-1 px-2 text-[10px] font-semibold uppercase tracking-[0.1em] text-muted-foreground/50">
                      {group.label}
                    </p>
                  )}
                  <div className="space-y-0.5">
                    {group.items.map((item) => (
                      <MobileNavItem
                        key={item.href}
                        item={item}
                        isActive={
                          item.href === '/dashboard'
                            ? pathname === item.href
                            : pathname.startsWith(item.href.split('?')[0] ?? item.href)
                        }
                        onNavigate={() => setOpen(false)}
                        plan={plan}
                        dynamicBadges={dynamicBadges}
                      />
                    ))}
                  </div>
                </div>
              ))}
            </nav>
          </ScrollArea>

          <div className="border-t border-border/60 p-3 safe-bottom">
            <Button
              variant="ghost"
              className="w-full justify-start gap-2.5 text-[13px] text-destructive hover:bg-destructive/10 hover:text-destructive"
              onClick={() => { setOpen(false); onSignOut() }}
            >
              <LogOut className="size-4" aria-hidden="true" />
              Sign out
            </Button>
          </div>
        </SheetContent>
      </Sheet>
    </>
  )
}

'use client'

import { useState } from 'react'
import { useRouter } from 'next/navigation'
import Image from 'next/image'
import { Check, ChevronsUpDown, Loader2 } from 'lucide-react'
import { toast } from 'sonner'
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuLabel,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from '@/components/ui/dropdown-menu'
import { PlanBadge } from '@/components/shared/PlanBadge'
import { cn } from '@/lib/utils'
import type { StudioMembership } from '@/lib/context/active-studio'

interface StudioSwitcherProps {
  currentStudioId: string
  allMemberships: StudioMembership[]
}

function getMonogram(name: string): string {
  return name
    .split(' ')
    .slice(0, 2)
    .map((w) => w[0] ?? '')
    .join('')
    .toUpperCase()
}

interface StudioLogoProps {
  name: string
  logoUrl: string | null
  className?: string
  monogramClassName?: string
}

function StudioLogo({ name, logoUrl, className, monogramClassName }: StudioLogoProps) {
  if (logoUrl) {
    return (
      <Image
        src={logoUrl}
        alt={name}
        width={28}
        height={28}
        className={cn('rounded object-cover', className)}
        aria-hidden="true"
      />
    )
  }
  return (
    <span
      className={cn(
        'flex items-center justify-center rounded bg-primary/10 font-bold text-primary',
        monogramClassName,
        className,
      )}
      aria-hidden="true"
    >
      {getMonogram(name)}
    </span>
  )
}

export function StudioSwitcher({ currentStudioId, allMemberships }: StudioSwitcherProps) {
  const router = useRouter()
  const [pendingId, setPendingId] = useState<string | null>(null)

  const currentMembership = allMemberships.find((m) => m.studioId === currentStudioId)
  const studioName = currentMembership?.studio.name ?? 'Studio'
  const logoUrl = currentMembership?.studio.logo_url ?? null

  async function handleSwitch(studioId: string) {
    if (studioId === currentStudioId || pendingId !== null) return
    setPendingId(studioId)
    try {
      const res = await fetch('/api/context/set-studio', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ studioId }),
      })
      if (!res.ok) {
        throw new Error('Switch failed')
      }
      router.refresh()
    } catch {
      toast.error('Failed to switch studio. Try again.')
      setPendingId(null)
    }
  }

  const isSwitching = pendingId !== null

  return (
    <DropdownMenu>
      <DropdownMenuTrigger
        render={
          <button
            type="button"
            aria-haspopup="listbox"
            aria-label="Switch studio"
            className={cn(
              'flex h-8 max-w-[200px] items-center gap-1.5 rounded-lg border border-border/60 bg-transparent px-2',
              'text-[13px] font-medium text-foreground transition-colors duration-100',
              'hover:bg-muted/50',
              'focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-1',
              isSwitching && 'pointer-events-none opacity-70',
            )}
          />
        }
      >
        <StudioLogo
          name={studioName}
          logoUrl={logoUrl}
          className="h-5 w-5 shrink-0 text-[10px]"
        />
        <span className="truncate">{studioName}</span>
        <ChevronsUpDown className="h-3.5 w-3.5 shrink-0 text-muted-foreground/50 transition-transform duration-150 data-[state=open]:rotate-180" aria-hidden="true" />
      </DropdownMenuTrigger>

      <DropdownMenuContent
        side="bottom"
        align="start"
        sideOffset={8}
        className="w-64 max-h-80 overflow-y-auto rounded-xl border-border/60 p-1.5 shadow-[var(--shadow-lift)]"
      >
        <DropdownMenuLabel className="px-2 pb-1 text-[11px] font-semibold uppercase tracking-wide text-muted-foreground/60">
          Switch studio
        </DropdownMenuLabel>
        <DropdownMenuSeparator />

        {allMemberships.map((membership) => {
          const isActive = membership.studioId === currentStudioId
          const isPending = membership.studioId === pendingId

          return (
            <DropdownMenuItem
              key={membership.studioId}
              onClick={() => void handleSwitch(membership.studioId)}
              className="flex cursor-pointer items-center gap-2.5 rounded-md px-2 py-2 text-[13px] hover:bg-accent focus:bg-accent"
            >
              <StudioLogo
                name={membership.studio.name}
                logoUrl={membership.studio.logo_url}
                className="h-7 w-7 shrink-0 text-[10px]"
              />
              <div className="flex-1 min-w-0">
                <p className="truncate text-[13px] font-medium leading-tight">
                  {membership.studio.name}
                </p>
