 *  - New prop: onMoreOpen — opens the MobileNav sheet
 *  - "Settings" right slot replaced by "More" (triggers MobileNav sheet)
 *  - "Dashboard" left slot label updated to "Home"
 *  - "Schedule" routes to /calendar
 *  - Active state: icon + label in primary color
 *  - isActive guard: empty href returns false (More slot)
 */

interface BottomNavProps {
  /** Opens the quick-create menu (appointment, client, consent, invite) */
  onNew: () => void
  /** Opens the MobileNav full-tree sheet */
  onMoreOpen: () => void
}

interface NavSlot {
  icon: React.ComponentType<{ className?: string }>
  label: string
  href: string
}

const LEFT_SLOTS: NavSlot[] = [
  { icon: LayoutDashboard, label: 'Home',     href: '/dashboard' },
  { icon: CalendarDays,    label: 'Schedule', href: '/calendar' },
]

const RIGHT_SLOTS: NavSlot[] = [
  { icon: Users,          label: 'Clients', href: '/clients' },
  // More slot — href is empty, rendered as button via MoreButton component
  { icon: MoreHorizontal, label: 'More',    href: '' },
]

export function BottomNav({ onNew, onMoreOpen }: BottomNavProps) {
  const pathname = usePathname()

  function isActive(href: string) {
    if (!href) return false
    if (href === '/dashboard') return pathname === '/dashboard'
    return pathname.startsWith(href)
  }

  return (
    <nav
      aria-label="Primary navigation"
      className={cn(
        'flex md:hidden',
        'fixed bottom-0 left-0 right-0 z-40',
        'h-16 pb-safe',
