        'border-t border-border/60',
        'shadow-[0_-1px_0_0_hsl(var(--border)/0.5)]',
      )}
    >
      {/* Left 2 slots */}
      {LEFT_SLOTS.map((slot) => (
        <NavLink key={slot.href} slot={slot} active={isActive(slot.href)} />
      ))}

      {/* Center FAB — primary create action */}
      <div className="flex flex-1 items-center justify-center">
        <button
          type="button"
          onClick={onNew}
          aria-label="New"
          className={cn(
            'flex flex-col items-center justify-center',
            'h-14 w-14 rounded-full',
            '-translate-y-4',
            'bg-primary text-primary-foreground',
            'shadow-[var(--shadow-soft-md,var(--shadow-card))]',
            'transition-transform active:scale-95',
            'touch-manipulation',
          )}
        >
          <Plus className="h-6 w-6" aria-hidden="true" />
        </button>
      </div>

      {/* Right 2 slots */}
      <NavLink slot={RIGHT_SLOTS[0]!} active={isActive(RIGHT_SLOTS[0]!.href)} />
      <MoreButton onMoreOpen={onMoreOpen} />
    </nav>
  )
}

function NavLink({ slot, active }: { slot: NavSlot; active: boolean }) {
  const { icon: Icon, label, href } = slot
  return (
    <Link
      href={href}
      className={cn(
        'flex flex-1 flex-col items-center justify-center gap-1',
        'min-h-[44px] min-w-[44px]',
        'transition-colors duration-150',
        active ? 'text-primary' : 'text-muted-foreground hover:text-foreground',
      )}
      aria-current={active ? 'page' : undefined}
    >
      <Icon className="h-5 w-5 shrink-0" aria-hidden="true" />
      <span className="text-[10px] font-medium tracking-tight leading-none">{label}</span>
    </Link>
  )
}

function MoreButton({ onMoreOpen }: { onMoreOpen: () => void }) {
  const Icon = MoreHorizontal
  return (
    <button
      type="button"
      onClick={onMoreOpen}
      aria-label="Open navigation menu"
      className={cn(
